import {
    Group,
    Mesh,
    PlaneGeometry,
    Vector3,
    Euler,
    Texture,
    MeshBasicNodeMaterial,
    NodeMaterial,
    uvNode,
    textureNode,
    mul,
    add,
    vec2,
    vec4,
    color,
    positionNode,
    transformDirectionNode
} from 'three/webgpu';
import { gsap } from 'gsap';

/**
 * @typedef {Object} PrimitiveSpec
 * @property {string} name
 * @property {Object} params
 */

/**
 * @typedef {Object} NodeConfig
 * @property {Object} assets
 * @property {string} assets.imageUrl
 * @property {Array<PrimitiveSpec>} cinematicPrimitives
 * @property {Object} textContent
 * @property {Array<string>} textContent.lines
 * @property {Object} placement
 * @property {Array<number>} placement.position
 * @property {Array<number>} placement.rotation
 * @property {Array<number>} placement.scale
 */

/**
 * @typedef {Object} NodeContext
 * @property {(url:string)=>Texture} textureLoader
 * @property {{[key:string]:(obj:THREE.Object3D,params:any)=>void}} primitives
 * @property {{texture:Texture}} fontAtlas
 * @property {{emit:(event:string)=>void}} eventBus
 */

/**
 * Create a journal card node.
 * @param {NodeConfig} config
 * @param {NodeContext} ctx
 * @returns {THREE.Object3D}
 */
export default function createNode(config, ctx) {
    // --------------------------------------------------------------------
    // Base group ---------------------------------------------------------
    const root = new Group();

    // --------------------------------------------------------------------
    // Load the main texture -----------------------------------------------
    const mainTex = ctx.textureLoader(config.assets.imageUrl);

    // --------------------------------------------------------------------
    // Plane geometry -------------------------------------------------------
    const planeGeom = new PlaneGeometry(1, 1);
    const planeMat = new MeshBasicNodeMaterial({ map: mainTex, transparent: true });
    const planeMesh = new Mesh(planeGeom, planeMat);
    root.add(planeMesh);

    // --------------------------------------------------------------------
    // Text rendering -------------------------------------------------------
    // Simple UV‑transform to sample the required atlas region.
    // Atlas region: x=0, y=0, w=512, h=320 (pixel units)
    // We assume the atlas texture size is known via ctx.fontAtlas.texture.image (fallback to 1024).
    const atlasTex = ctx.fontAtlas.texture;
    const atlasImage = atlasTex.image ?? { width: 1024, height: 1024 };
    const region = { x: 0, y: 0, w: 512, h: 320 };
    const uvScale = vec2(region.w / atlasImage.width, region.h / atlasImage.height);
    const uvOffset = vec2(region.x / atlasImage.width, region.y / atlasImage.height);

    const uvTransformNode = add(mul(uvNode(), uvScale), uvOffset);
    const textMat = new MeshBasicNodeMaterial({
        map: atlasTex,
        transparent: true,
        depthWrite: false,
        alphaTest: 0.01,
        // replace default UV with transformed UV
        uvNode: () => uvTransformNode
    });

    const textGeom = new PlaneGeometry(0.9, 0.2);
    const textMesh = new Mesh(textGeom, textMat);
    // Slight offset so text sits just above the image plane
    textMesh.position.set(0, 0, 0.001);
    root.add(textMesh);

    // --------------------------------------------------------------------
    // Position / rotation / scale -----------------------------------------
    const [px, py, pz] = config.placement.position || [0, 0, 0];
    const [rx, ry, rz] = config.placement.rotation || [0, 0, 0];
    const [sx, sy, sz] = config.placement.scale || [1, 1, 1];
    root.position.set(px, py, pz);
    root.rotation.set(rx, ry, rz);
    root.scale.set(sx, sy, sz);

    // Keep base Y for hover animation
    const baseY = root.position.y;

    // --------------------------------------------------------------------
    // Cinematic primitives -------------------------------------------------
    if (Array.isArray(config.cinematicPrimitives)) {
        for (const prim of config.cinematicPrimitives) {
            const fn = ctx.primitives[prim.name];
            if (typeof fn === 'function') {
                fn(root, prim.params);
            }
        }
    }

    // --------------------------------------------------------------------
    // Interaction handlers -------------------------------------------------
    const timelines = {};

    const hoverEnter = () => {
        const key = 'hoverRise';
        if (timelines[key]) timelines[key].kill();
        timelines[key] = gsap.to(root.position, {
            y: baseY + 0.15,
            duration: 0.7,
            ease: 'power3.out'
        });
    };

    const hoverLeave = () => {
        const key = 'hoverRise';
        if (timelines[key]) timelines[key].kill();
        timelines[key] = gsap.to(root.position, {
            y: baseY,
            duration: 0.7,
            ease: 'power3.out'
        });
    };

    const clickHandler = () => {
        if (ctx.eventBus && typeof ctx.eventBus.emit === 'function') {
            ctx.eventBus.emit('hub-journal.select');
        }
    };

    root.userData.handlers = {
        hoverEnter,
        hoverLeave,
        click: clickHandler
    };

    // --------------------------------------------------------------------
    // Cleanup -------------------------------------------------------------
    root.userData.cleanup = () => {
        // Dispose geometries
        planeGeom.dispose();
        textGeom.dispose();

        // Dispose materials
        planeMat.dispose();
        textMat.dispose();

        // Dispose textures (only dispose if they were created here)
        if (mainTex && typeof mainTex.dispose === 'function') mainTex.dispose();
        // Do NOT dispose the shared font atlas texture – it may be reused elsewhere.

        // Kill any lingering GSAP tweens
        for (const key in timelines) {
            if (timelines[key]) timelines[key].kill();
        }
        gsap.killTweensOf(root.position);
    };

    return root;
}
